{"path": "dominoes.py", "content": "def can_chain(dominoes):
    """Return a list of stones forming a closed domino chain, or None."""
    stones = [tuple(stone) for stone in dominoes]
    if not stones:
        return []

    used = [False] * len(stones)
    chain = [stones[0]]
    used[0] = True

    def search():
        if len(chain) == len(stones):
            return chain[0][0] == chain[-1][1]
        end = chain[-1][1]
        tried = set()
        for index, (left, right) in enumerate(stones):
            if used[index]:
                continue
            for oriented in ((left, right), (right, left)):
                if oriented[0] != end or oriented in tried:
                    continue
                tried.add(oriented)
                used[index] = True
                chain.append(oriented)
                if search():
                    return True
                chain.pop()
                used[index] = False
        return False

    return list(chain) if search() else None
